from pathlib import Path
import sys

ops = [('insert_before', 'lib/contributions/stripe-server.ts', 'export async function createContributionCheckout(input: {', 'export async function retrieveContributionCheckoutSession(\n  checkoutSessionId: string,\n) {\n  const id = checkoutSessionId.trim();\n\n  if (!id) {\n    throw new Error("Stripe Checkout Session ID is required.");\n  }\n\n  return stripeClient().checkout.sessions.retrieve(id, {\n    expand: ["payment_intent"],\n  });\n}\n\n'), ('replace', 'app/(portal)/contribution/actions.ts', '  ensureContributionProductReady,\n} from "@/lib/contributions/stripe-server";\n', '  ensureContributionProductReady,\n  retrieveContributionCheckoutSession,\n} from "@/lib/contributions/stripe-server";\nimport { sendContributionThankYouEmail } from "@/lib/contributions/contribution-email";\n'), ('replace_func', 'app/(portal)/contribution/actions.ts', 'export async function getContributionCheckoutStatus(', '\nexport async function startContributionCheckout(', 'export async function getContributionCheckoutStatus(\n  checkoutSessionId: string,\n): Promise<{ status: string | null; paid: boolean }> {\n  const sessionId = checkoutSessionId.trim();\n  if (!sessionId) return { status: null, paid: false };\n\n  const supabase = await createClient();\n  const admin = createAdminClient();\n\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) return { status: null, paid: false };\n\n  const { data: contribution, error } = await admin\n    .from("support_contributions")\n    .select(\n      "id, status, amount_minor, stripe_checkout_session_id, stripe_payment_intent_id, stripe_charge_id",\n    )\n    .eq("user_id", user.id)\n    .eq("stripe_checkout_session_id", sessionId)\n    .maybeSingle();\n\n  if (error || !contribution) {\n    return { status: null, paid: false };\n  }\n\n  const alreadyPaid =\n    contribution.status === "paid" ||\n    contribution.status === "partially_refunded" ||\n    contribution.status === "refunded";\n\n  if (alreadyPaid) {\n    return { status: contribution.status, paid: true };\n  }\n\n  try {\n    const session = await retrieveContributionCheckoutSession(sessionId);\n\n    if (\n      session.metadata?.sepulchria_payment_type !== "contribution" ||\n      session.metadata?.contribution_id !== contribution.id ||\n      session.metadata?.sepulchria_user_id !== user.id\n    ) {\n      return { status: contribution.status, paid: false };\n    }\n\n    if (session.payment_status !== "paid") {\n      return { status: contribution.status, paid: false };\n    }\n\n    const paymentIntent =\n      session.payment_intent &&\n      typeof session.payment_intent !== "string"\n        ? session.payment_intent\n        : null;\n\n    const paymentIntentId =\n      typeof session.payment_intent === "string"\n        ? session.payment_intent\n        : paymentIntent?.id ?? null;\n\n    const latestCharge = paymentIntent?.latest_charge;\n\n    const chargeId =\n      typeof latestCharge === "string"\n        ? latestCharge\n        : latestCharge?.id ?? contribution.stripe_charge_id ?? null;\n\n    const amountMinor =\n      typeof session.amount_total === "number"\n        ? session.amount_total\n        : Number(contribution.amount_minor);\n\n    const { error: updateError } = await admin\n      .from("support_contributions")\n      .update({\n        status: "paid",\n        amount_minor: amountMinor,\n        stripe_payment_intent_id:\n          paymentIntentId ?? contribution.stripe_payment_intent_id ?? null,\n        stripe_charge_id: chargeId,\n        stripe_customer_id:\n          typeof session.customer === "string"\n            ? session.customer\n            : session.customer?.id ?? null,\n        paid_at: new Date().toISOString(),\n        updated_at: new Date().toISOString(),\n      })\n      .eq("id", contribution.id);\n\n    if (updateError) {\n      console.error(\n        "Unable to reconcile paid Contribution from Stripe Checkout Session:",\n        updateError,\n      );\n      return { status: contribution.status, paid: false };\n    }\n\n    try {\n      await sendContributionThankYouEmail(contribution.id);\n    } catch (emailError) {\n      console.error(\n        "Contribution was reconciled as paid, but thank-you email failed:",\n        emailError,\n      );\n    }\n\n    return { status: "paid", paid: true };\n  } catch (stripeError) {\n    console.error(\n      "Unable to verify Contribution Checkout Session directly with Stripe:",\n      stripeError,\n    );\n\n    return { status: contribution.status, paid: false };\n  }\n}\n\n'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'className="text-[9px] tracking-[0.08em] text-[rgb(var(--sep-colour-806b50))]"', 'className="normal-case text-[9px] tracking-[0.08em] text-[rgb(var(--sep-colour-806b50))]"'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'className="mt-1 font-serif text-xl text-[rgb(var(--sep-colour-d8bf91))]"', 'className="mt-1 font-serif text-xl normal-case text-[rgb(var(--sep-colour-d8bf91))]"'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'className="normal-case border border-[rgb(var(--sep-colour-60482e))]/55 px-3 py-2 text-[10px] text-[rgb(var(--sep-colour-d7c4a5))]"', 'className="normal-case border border-[rgb(var(--sep-colour-60482e))]/55 px-3 py-2 text-[10px] text-[rgb(var(--sep-colour-d7c4a5))]"'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'className="border border-[rgb(var(--sep-colour-60482e))]/55 px-3 py-2 text-[10px] text-[rgb(var(--sep-colour-d7c4a5))]"', 'className="normal-case border border-[rgb(var(--sep-colour-60482e))]/55 px-3 py-2 text-[10px] text-[rgb(var(--sep-colour-d7c4a5))]"'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'className="font-serif text-2xl text-[#24180f]"', 'className="font-serif text-2xl normal-case text-[#24180f]"'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', '"relative border p-4 pr-24 text-left transition",', '"relative border p-4 pr-24 text-left normal-case transition",'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'className="absolute right-3 top-3 border border-[rgb(var(--sep-colour-b58a50))]/70 bg-[rgb(var(--sep-colour-211a14))] px-2 py-1 text-[9px] font-semibold text-[rgb(var(--sep-colour-efd6aa))]"', 'className="absolute right-3 top-3 normal-case border border-[rgb(var(--sep-colour-b58a50))]/70 bg-[rgb(var(--sep-colour-211a14))] px-2 py-1 text-[9px] font-semibold text-[rgb(var(--sep-colour-efd6aa))]"'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'className="block font-serif text-xl text-[rgb(var(--sep-colour-efd6aa))]"', 'className="block font-serif text-xl normal-case text-[rgb(var(--sep-colour-efd6aa))]"'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'className="mt-3 block font-serif text-2xl text-[rgb(var(--sep-colour-d8bf91))]"', 'className="mt-3 block font-serif text-2xl normal-case text-[rgb(var(--sep-colour-d8bf91))]"'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'className="mb-1 block text-[9px] tracking-[0.04em] text-[rgb(var(--sep-colour-8f8271))]"', 'className="mb-1 block normal-case text-[9px] tracking-[0.04em] text-[rgb(var(--sep-colour-8f8271))]"'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'className="mt-5 w-full border border-[rgb(var(--sep-colour-987344))]/70 bg-[rgb(var(--sep-colour-2a1d12))] px-5 py-3 text-[10px] tracking-[0.04em] text-[rgb(var(--sep-colour-efd9aa))] disabled:opacity-55"', 'className="mt-5 w-full normal-case border border-[rgb(var(--sep-colour-987344))]/70 bg-[rgb(var(--sep-colour-2a1d12))] px-5 py-3 text-[10px] tracking-[0.04em] text-[rgb(var(--sep-colour-efd9aa))] disabled:opacity-55"'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'Secure Contribution', 'Secure contribution'), ('optional_replace', 'components/contributions/contribution-checkout.tsx', 'Confirming Contribution', 'Confirming contribution'), ('optional_replace', 'app/(portal)/contribution/page.tsx', 'className="text-[9px] tracking-[0.08em] text-[rgb(var(--sep-colour-876a46))]"', 'className="normal-case text-[9px] tracking-[0.08em] text-[rgb(var(--sep-colour-876a46))]"'), ('optional_replace', 'app/(portal)/contribution/page.tsx', 'className="mt-2 font-serif text-3xl text-[rgb(var(--sep-colour-e5cfa6))]"', 'className="mt-2 font-serif text-3xl normal-case text-[rgb(var(--sep-colour-e5cfa6))]"'), ('optional_replace', 'app/(portal)/contribution/page.tsx', 'Sepulchria · Contribution', 'Sepulchria · contribution')]

loaded = {}
for op in ops:
    p = Path(op[1])
    if not p.exists():
        raise SystemExit(f"ERROR: Missing {p}. Run from repository root.")
    if p not in loaded:
        loaded[p] = p.read_text(encoding="utf-8")

for op in ops:
    kind, path_s = op[0], op[1]
    p = Path(path_s)
    src = loaded[p]
    if kind == 'replace':
        old, new = op[2], op[3]
        if src.count(old) != 1:
            raise SystemExit(f"ERROR: {p}: expected one exact match.")
        src = src.replace(old, new, 1)
    elif kind == 'insert_before':
        marker, ins = op[2], op[3]
        if ins.strip() in src:
            pass
        else:
            if src.count(marker) != 1:
                raise SystemExit(f"ERROR: {p}: insert marker not unique.")
            src = src.replace(marker, ins + marker, 1)
    elif kind == 'replace_func':
        start_m, end_m, new_text = op[2], op[3], op[4]
        a = src.find(start_m)
        b = src.find(end_m, a)
        if a < 0 or b < 0:
            raise SystemExit(f"ERROR: {p}: function markers not found.")
        src = src[:a] + new_text + src[b:]
    elif kind == 'optional_replace':
        old, new = op[2], op[3]
        if old != new and old in src:
            src = src.replace(old, new, 1)
    loaded[p] = src

for p, src in loaded.items():
    p.write_text(src, encoding="utf-8")

print("Patched direct Stripe reconciliation + normal-case UI.")
print("Run: npm run build")
